 private String page="info";private final LinkedHashSet<Path> recent=new LinkedHashSet<>();private final javax.swing.Timer poll;
 private boolean continuation;private String signature="";private String pendingRename;
 private static final String[][] COMMANDS={{"info","File info"},{"new","New"},{"open","Open…"},{"recent","Recent files"},{"save","Save"},{"save-as","Save As…"},{"rename","Rename…"},{"import","Import…"},{"export","Export…"},{"print","Print…"},{"close","Close file"}};
