  rail.setLayout(new BoxLayout(rail,BoxLayout.Y_AXIS));rail.setBackground(new Color(0xF5F0F9));rail.setBorder(BorderFactory.createEmptyBorder(14,12,14,12));rail.setPreferredSize(new Dimension(202,500));
  JScrollPane navigation=new JScrollPane(rail);navigation.setBorder(BorderFactory.createMatteBorder(0,0,0,1,StudioVisuals.BORDER));navigation.setPreferredSize(new Dimension(202,400));navigation.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);add(navigation,BorderLayout.WEST);
  JPanel sheet=new JPanel(new BorderLayout());sheet.setBackground(StudioVisuals.SURFACE);add(sheet);
  head.setOpaque(false);head.setBorder(BorderFactory.createEmptyBorder(20,30,14,30));JLabel eyebrow=new JLabel("CURRENT TEMPLATE");eyebrow.setForeground(new Color(0x8E709F));eyebrow.setFont(StudioVisuals.font(Font.BOLD,11));head.add(eyebrow,BorderLayout.NORTH);title.setFont(StudioVisuals.font(Font.BOLD,27));head.add(title);subtitle.setForeground(new Color(0x81738A));head.add(subtitle,BorderLayout.SOUTH);sheet.add(head,BorderLayout.NORTH);
